        match: match.title,
        bet: bet.getBetName(),
        linkId: 0,
        createAt: Date.now(),
        isCreateOrder: true,
        betCount: 1,
      });
      this.createOrder(order);
    },

    /** [changmen 扩展] 清除原单锁与消费一次队列合并为一次存储写入。 */
    consumeOrder(order: LoseOrder) {
      if (this.orders.get(order.betId) !== order)
        return;
      this.clearPendingVenueOrder(order.betId, false);
      this.removeOrder(order.betId);
    },

    removeOrder(betId: number, force = false) {
      const existing = this.orders.get(betId);
      if (!existing)
        return;
      const next = new Map(this.orders);
      if (!force && existing.betCount > 1) {
        existing.betCount -= 1;
        next.set(betId, existing);
      }
      else {
        next.delete(betId);
        observeOrder(existing.observation, existing.linkId, "queue_removed", { target: existing.target, source: "business_queue", reasonCode: "business_remove" });
